using System;
using System.Text;
using Jaunt.Runtime.Regex;

namespace Jaunt.Runtime;

/// <summary>
/// Locale-independent full case conversion (String.prototype.toLowerCase / toUpperCase): UnicodeData.txt simple
/// mappings plus the unconditional SpecialCasing.txt mappings (e.g. ß → SS, İ → i̇), and the Final_Sigma context
/// rule for U+03A3. Tables are generated by tools/unicode/casing.py (Unicode 17).
/// </summary>
internal static partial class CaseMapping
{
    private static int[]? s_cased, s_caseIgnorable;

    public static string ToLower(string s)
    {
        int i = 0;
        // ASCII fast path: nothing to do until the first upper-case or non-ASCII char
        for (; i < s.Length; i++)
        {
            char c = s[i];
            if (c >= 0x80 || (c >= 'A' && c <= 'Z')) break;
        }
        if (i == s.Length) return s;
        var sb = new StringBuilder(s.Length);
        sb.Append(s, 0, i);
        for (; i < s.Length; i++)
        {
            char c = s[i];
            if (c < 0x80) { sb.Append(c >= 'A' && c <= 'Z' ? (char)(c + 32) : c); continue; }
            int cp = c;
            int width = 1;
            if (char.IsHighSurrogate(c) && i + 1 < s.Length && char.IsLowSurrogate(s[i + 1])) { cp = char.ConvertToUtf32(c, s[i + 1]); width = 2; }
            if (cp == 0x3A3 && IsFinalSigma(s, i)) sb.Append('ς');
            else AppendMapped(sb, s, i, width, cp, LowerKeys, LowerValues);
            i += width - 1;
        }
        return sb.ToString();
    }

    public static string ToUpper(string s)
    {
        int i = 0;
        for (; i < s.Length; i++)
        {
            char c = s[i];
            if (c >= 0x80 || (c >= 'a' && c <= 'z')) break;
        }
        if (i == s.Length) return s;
        var sb = new StringBuilder(s.Length);
        sb.Append(s, 0, i);
        for (; i < s.Length; i++)
        {
            char c = s[i];
            if (c < 0x80) { sb.Append(c >= 'a' && c <= 'z' ? (char)(c - 32) : c); continue; }
            int cp = c;
            int width = 1;
            if (char.IsHighSurrogate(c) && i + 1 < s.Length && char.IsLowSurrogate(s[i + 1])) { cp = char.ConvertToUtf32(c, s[i + 1]); width = 2; }
            AppendMapped(sb, s, i, width, cp, UpperKeys, UpperValues);
            i += width - 1;
        }
        return sb.ToString();
    }

    private static void AppendMapped(StringBuilder sb, string s, int i, int width, int cp, int[] keys, string[] values)
    {
        int k = Array.BinarySearch(keys, cp);
        if (k >= 0) sb.Append(values[k]);
        else sb.Append(s, i, width);
    }

    // Final_Sigma: preceded by a cased letter (skipping case-ignorable chars) and not followed by one
    private static bool IsFinalSigma(string s, int at)
    {
        bool before = false;
        for (int j = at; j > 0;)
        {
            int cp = PrevCodePoint(s, ref j);
            if (Has(CaseIgnorable, cp)) continue;
            before = Has(Cased, cp);
            break;
        }
        if (!before) return false;
        for (int j = at + 1; j < s.Length;)
        {
            int cp = NextCodePoint(s, ref j);
            if (Has(CaseIgnorable, cp)) continue;
            return !Has(Cased, cp);
        }
        return true;
    }

    private static int PrevCodePoint(string s, ref int j)
    {
        char c = s[--j];
        if (char.IsLowSurrogate(c) && j > 0 && char.IsHighSurrogate(s[j - 1])) { j--; return char.ConvertToUtf32(s[j], c); }
        return c;
    }

    private static int NextCodePoint(string s, ref int j)
    {
        char c = s[j++];
        if (char.IsHighSurrogate(c) && j < s.Length && char.IsLowSurrogate(s[j])) return char.ConvertToUtf32(c, s[j++]);
        return c;
    }

    private static int[] Cased => s_cased ??= Load("Cased");
    private static int[] CaseIgnorable => s_caseIgnorable ??= Load("Case_Ignorable");

    private static int[] Load(string name) =>
        UnicodeData.TryGetProperty(name, null, out var r) ? r : throw new InvalidOperationException("missing Unicode property " + name);

    private static bool Has(int[] ranges, int cp)
    {
        int lo = 0, hi = ranges.Length / 2 - 1;
        while (lo <= hi)
        {
            int mid = (lo + hi) >> 1;
            if (cp < ranges[2 * mid]) hi = mid - 1;
            else if (cp > ranges[2 * mid + 1]) lo = mid + 1;
            else return true;
        }
        return false;
    }
}
